INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4478847d-7e5d-4e56-8aa6-335144b7c1df', 'a58a0c95-e0dd-43dc-89b2-10c552b7ddff', 0, 'Confidentiality — hashing is used here because it hides the file''s contents from anyone who does not have the decryption key.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d0e739c-5b49-45ac-b5c2-211278197ffb', 'a58a0c95-e0dd-43dc-89b2-10c552b7ddff', 1, 'Integrity — a cryptographic hash produces a fixed-size fingerprint that changes if even one bit of the input changes, so comparing hashes confirms the file is byte-for-byte identical to the original; hashing is used (not encryption) because the goal is verification, not concealment, and hashing is one-way (not meant to be reversed).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5239e0a-c48e-4df9-b3e7-82282167acde', 'a58a0c95-e0dd-43dc-89b2-10c552b7ddff', 2, 'Non-repudiation — hashing proves who sent the file and prevents them from denying it.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8d55c93-db29-4384-af29-c8395ecc41fa', 'a58a0c95-e0dd-43dc-89b2-10c552b7ddff', 3, 'Availability — hashing ensures the file will always be downloadable in the future.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7612c33-8f89-4a5f-868c-784ee3442754', 'b7130166-6242-4fcd-b55d-507f0e3ed89d', 0, 'The CA''s role is to store every server''s private key centrally; if a private key is compromised, nothing needs to happen since the CA can simply issue a new copy of the same key.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f6dd7835-af12-41d8-8d0f-b4f921cde203', 'b7130166-6242-4fcd-b55d-507f0e3ed89d', 1, 'The CA is a trusted third party that issues and digitally signs certificates, vouching that a given public key genuinely belongs to the named entity; if a private key is compromised, the corresponding certificate must be revoked (e.g., via a CRL or OCSP) so relying parties stop trusting it, and a new key pair/certificate must be issued.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da6cc938-9443-4ed7-9584-e6365f15b469', 'b7130166-6242-4fcd-b55d-507f0e3ed89d', 2, 'The CA has no role once a certificate is issued, and a compromised private key has no security implications as long as the certificate has not expired.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86589183-f4ad-4115-a988-ba260a9f753f', 'b7130166-6242-4fcd-b55d-507f0e3ed89d', 3, 'The CA''s only function is to generate random encryption keys for VPN tunnels, unrelated to certificates.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c9833d36-2549-45b6-940a-69334a9b6753', '997f460a-2ae4-4359-96a5-2e262df54773', 0, 'Patches should never be applied to production servers under any circumstances, since patching itself is the security risk.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('605de470-a8d7-40e2-b61f-e31e625a361a', '997f460a-2ae4-4359-96a5-2e262df54773', 1, 'The process likely lacks consistent tracking/enforcement (e.g., an inventory of what needs patching, a defined patch testing and deployment cadence, and verification that patches actually applied) — a written policy alone does not patch systems; the process needs measurable, enforced execution with visibility into which systems are actually up to date.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('41e24cfe-2b34-45d1-91a9-1552dafc5250', '997f460a-2ae4-4359-96a5-2e262df54773', 2, 'This is not a real operational risk as long as a firewall exists somewhere on the network.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4201d5dc-68be-4599-989f-766d6d08fb0a', '997f460a-2ae4-4359-96a5-2e262df54773', 3, 'Patch management is solely the responsibility of the software vendor, not the organization running the software.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('24ee86df-f9aa-4e99-a2f2-37d1c7bf2514', 'd6d09dd4-37f3-4678-9ba1-114c71c86cfe', 0, 'Tailgating (or piggybacking); mitigated by controls like mantraps (interlocking doors allowing only one person through per authenticated badge scan) and a security-awareness culture of not holding doors open for unbadged individuals.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('37de4c91-3d78-4a2c-9034-6371804ed0ed', 'd6d09dd4-37f3-4678-9ba1-114c71c86cfe', 1, 'Whaling; mitigated by antivirus software installed on the server room''s door lock system.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('170625a6-634a-4747-a28a-46ae76371b2d', 'd6d09dd4-37f3-4678-9ba1-114c71c86cfe', 2, 'Vishing; mitigated by disabling the phone lines in the server room.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c2b6f7c-fb01-4dd4-a372-0c199336ec52', 'd6d09dd4-37f3-4678-9ba1-114c71c86cfe', 3, 'SQL injection; mitigated by parameterized queries on the badge reader''s database.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0473cffd-beff-47cf-b90c-8940bdda29d3', '5a015e0c-a976-4056-a47f-32935953bcb2', 0, 'In passive/monitoring mode it is an IDS (Intrusion Detection System, which alerts but does not block); in inline/active-blocking mode it is an IPS (Intrusion Prevention System, which can automatically block detected malicious traffic in real time).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b11a811-b205-44e6-ba8e-369308d5bb5c', '5a015e0c-a976-4056-a47f-32935953bcb2', 1, 'IDS and IPS are fully interchangeable terms describing identical capability with no distinction in blocking behavior.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('988a6077-0571-4f12-9353-1411998e4754', '5a015e0c-a976-4056-a47f-32935953bcb2', 2, 'This device is called a VPN concentrator regardless of which mode it operates in.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('71ebebd8-28b5-4603-b844-fdaf4fcd4add', '5a015e0c-a976-4056-a47f-32935953bcb2', 3, 'This device is only ever called a firewall, and firewalls and IDS/IPS are the same technology.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('040c7d6b-c9ec-4986-9e34-84e67a735ebc', '51d7ec57-8469-4ab3-9290-8e9451b49c92', 0, 'A VPN (Virtual Private Network), which creates an encrypted tunnel over an untrusted network (like the public internet), protecting the confidentiality of traffic passing through it between the remote endpoint and the corporate network.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('600be3c7-91c0-449d-be69-4233b0996e2d', '51d7ec57-8469-4ab3-9290-8e9451b49c92', 1, 'A DMZ, since DMZs are what create encrypted tunnels for remote employees.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce80c341-be19-4743-9120-6e90098afc99', '51d7ec57-8469-4ab3-9290-8e9451b49c92', 2, 'A honeypot, since honeypots are designed to securely connect remote employees to the corporate network.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a95a99a5-848c-40c5-b117-fae41ff3e84f', '51d7ec57-8469-4ab3-9290-8e9451b49c92', 3, 'A load balancer, since load balancers provide encrypted remote connectivity for individual employees.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5ce3504-354b-4845-98af-78764dbb094a', 'c8fbb0ee-cbe0-4afd-91cc-908292b4e290', 0, 'Micro-segmentation — applying granular network policies BETWEEN individual workloads/microservices (not just at the traditional network perimeter), so that a compromised service only has network access to the specific other services it genuinely needs to communicate with, not the entire environment.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('28fe0d96-c450-4ef7-8ed5-5fc62218a063', 'c8fbb0ee-cbe0-4afd-91cc-908292b4e290', 1, 'Allowing all microservices unrestricted network access to each other by default, since restricting internal traffic provides no security benefit once perimeter security exists.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59d22ff5-13f9-4965-a6ed-8c8f755d21df', 'c8fbb0ee-cbe0-4afd-91cc-908292b4e290', 2, 'Relying exclusively on a single perimeter firewall at the network edge, with no internal traffic restrictions between services.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8f47296-ee1a-4cce-9129-f772e1b738c3', 'c8fbb0ee-cbe0-4afd-91cc-908292b4e290', 3, 'Micro-segmentation refers only to physically splitting a data center into smaller buildings, unrelated to network policy.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('43a37a1c-231a-48eb-9729-db44fb1d22e8', '5cdffc30-11cf-4147-b321-2fdeb342847e', 0, 'A honeynet (a network of honeypots) — a deliberately deployed decoy environment designed to attract attackers, allowing the security team to observe attacker behavior/techniques in a controlled setting while diverting them away from genuinely valuable production systems.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('faeb5fbf-8205-438a-a942-6085e594e1c3', '5cdffc30-11cf-4147-b321-2fdeb342847e', 1, 'A DMZ, since DMZs are specifically built with fake data to attract attackers.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f3e2c406-ab42-4506-8936-8a37318227b1', '5cdffc30-11cf-4147-b321-2fdeb342847e', 2, 'A SIEM, since SIEMs are decoy environments built to lure attackers.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('abc432dc-7760-44c8-b5cb-be2eac570461', '5cdffc30-11cf-4147-b321-2fdeb342847e', 3, 'A VPN concentrator, since VPN concentrators are designed to mimic production environments for attackers.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('809f8a3f-a167-416e-8a83-7543d38a0fbd', 'd2d5263b-47a5-4852-94ec-8259ea75690e', 0, 'Data classification — labeling data by sensitivity level so appropriately-scaled controls (encryption requirements, access restrictions, retention rules) can be applied; without it, organizations tend to either under-protect sensitive data or waste resources over-protecting everything uniformly, including data that doesn''t need it.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5349919-8980-45e4-9c03-2615855bfb74', 'd2d5263b-47a5-4852-94ec-8259ea75690e', 1, 'Data classification is purely a legal formality with no actual bearing on which technical security controls get applied.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c8cb659-0221-4f06-953c-5c19deef5bdc', 'd2d5263b-47a5-4852-94ec-8259ea75690e', 2, 'This practice is called encryption, since assigning labels to data is the definition of encrypting it.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('08aff25d-7d94-4cde-96f7-f6f662557b63', 'd2d5263b-47a5-4852-94ec-8259ea75690e', 3, 'This practice provides no security benefit, since all data should always receive identical maximum protection regardless of actual sensitivity.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0de5a35b-9aea-4dc0-9c17-9c5867d32f0f', '3d534325-5961-4929-9f13-8252ab42f2c8', 0, 'A failure in the offboarding/deprovisioning process — accounts should be disabled or removed as part of a defined offboarding checklist at (or immediately after) an employee''s departure date, not left active indefinitely; this is a common, real-world example of insider-threat risk persisting from a FORMER insider whose access was never properly revoked.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('71e0c2e3-cb03-4175-8439-5db4454a2a8b', '3d534325-5961-4929-9f13-8252ab42f2c8', 1, 'This is not a real security failure, since former employees have no meaningful ability to cause harm once they no longer work at the company.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('01ca5b91-cfd7-45b2-997d-25594ae1ebe2', '3d534325-5961-4929-9f13-8252ab42f2c8', 2, 'This is purely an HR issue with no security-team responsibility or overlap whatsoever.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('208ff887-b0d4-42c6-9a38-9b6564d6872a', '3d534325-5961-4929-9f13-8252ab42f2c8', 3, 'The correct fix is to give the former employee a new, stronger password rather than disabling the account.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('495b05f0-a7e0-4786-95cf-a2a46eae4dae', '78034a3f-5b12-475d-90c6-a77788a6ca9d', 0, 'A Business Impact Analysis (BIA) — systematically identifies critical business functions, quantifies the impact of their disruption over time, and establishes metrics like RTO (Recovery Time Objective — how quickly a function must be restored) and RPO (Recovery Point Objective — how much data loss, measured in time, is tolerable) that then guide DR/BCP investment priorities.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d98abbad-9fa9-4760-a3a5-1c5ac05dc095', '78034a3f-5b12-475d-90c6-a77788a6ca9d', 1, 'A vulnerability scan, since vulnerability scans are what determine business-function criticality and financial impact.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('73a9d616-8b7f-40c8-aedd-3c59b361a702', '78034a3f-5b12-475d-90c6-a77788a6ca9d', 2, 'A penetration test, since pen tests are designed to calculate financial impact of business function downtime.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f4bb8721-979b-4496-8ad9-6cbcd1bba952', '78034a3f-5b12-475d-90c6-a77788a6ca9d', 3, 'No formal process exists for this; business priorities are determined arbitrarily.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aaa0f337-3020-46a3-be43-e9b649f9bbe2', '23d05be7-5120-4dae-9dbf-af93cf506873', 0, 'Alert fatigue — when a high volume of false positives (or low-value alerts generally) causes analysts to become desensitized and start ignoring or dismissing alerts, including the rare genuine threats mixed in among the noise; the risk is a real incident being missed simply because it looked like "just another false alarm."');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8eecbf4d-e4a8-4b5f-a23f-6d7ba8078e20', '23d05be7-5120-4dae-9dbf-af93cf506873', 1, 'This is called "threat hunting," and it is a purely beneficial practice with no downside.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('68b834db-1c8b-41cf-987b-c7efc3530c9d', '23d05be7-5120-4dae-9dbf-af93cf506873', 2, 'This is called "zero-day exploitation," and it only affects unpatched systems.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('533f5cdf-27d4-4cfc-a455-73acf6839e54', '23d05be7-5120-4dae-9dbf-af93cf506873', 3, 'This has no name in security operations and carries no meaningful operational risk.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('223e0297-5957-46d7-bca9-305c91c2fd19', 'e800205a-9b7e-4ac4-beb7-7ab39106bed1', 0, 'Regular backup restoration testing — periodically actually restoring from backups (not just confirming the backup JOB completed) to verify the backups are genuinely usable, since a backup that has never been tested for restoration is not a verified, reliable backup at all.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9fba6370-917d-4dde-beb2-6500a9ff9939', 'e800205a-9b7e-4ac4-beb7-7ab39106bed1', 1, 'Increasing the backup frequency from daily to hourly, since frequency alone guarantees backup integrity.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d41c9590-aa25-4621-8b7b-91874cbdc23a', 'e800205a-9b7e-4ac4-beb7-7ab39106bed1', 2, 'Backups never need to be tested, since a completed backup job is always guaranteed to be restorable.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5d6cff2-9502-4c36-9050-e6692bb1c882', 'e800205a-9b7e-4ac4-beb7-7ab39106bed1', 3, 'Switching antivirus vendors, since antivirus software directly verifies backup restorability.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b487124d-61e7-4b86-9aa0-3745f40e2d50', '51b7d17b-6ec7-4bff-8cab-319b3ac76187', 0, 'NTP (Network Time Protocol) synchronization across all systems to a common, accurate time source, ensuring every system''s logs use consistent, comparable timestamps — without this, correlating events across multiple systems'' logs during an investigation becomes unreliable or outright impossible.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ae7f4e1-6f64-426a-882e-771d8e5cbe88', '51b7d17b-6ec7-4bff-8cab-319b3ac76187', 1, 'DNS, since DNS is responsible for synchronizing clocks across systems.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ddf078c9-5478-4d1a-8895-d20712dce2d0', '51b7d17b-6ec7-4bff-8cab-319b3ac76187', 2, 'DHCP, since DHCP''s primary function is time synchronization for log correlation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a919ec7-0389-45ef-a865-f7d9c889bf7f', '51b7d17b-6ec7-4bff-8cab-319b3ac76187', 3, 'Clock synchronization has no bearing on incident investigation or log analysis.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9cba3764-8b3e-4cc7-97b1-358a173381d8', '24b9c335-f6dc-414f-847c-e4cab37c8265', 0, 'Breach notification requirements are universally identical worldwide with one single global standard, so jurisdiction and data type are irrelevant to the determination.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('183d4eef-45a9-4214-beb2-ef8ea6cd7251', '24b9c335-f6dc-414f-847c-e4cab37c8265', 1, 'It primarily depends on the applicable jurisdiction(s) (based on where affected individuals reside and where the company operates) and the specific type of data involved (e.g., health data, payment card data, and general PII often carry different, specifically-defined notification obligations and timeframes under different laws).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a04abc6c-a359-45aa-9689-8fae9d5248d5', '24b9c335-f6dc-414f-847c-e4cab37c8265', 2, 'Notification is entirely optional and left to the company''s sole discretion in every jurisdiction, with no legal requirement anywhere.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c999eef3-41bb-465d-8593-89243ae8b717', '24b9c335-f6dc-414f-847c-e4cab37c8265', 3, 'Notification requirements depend solely on the size of the company''s IT budget.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d72dfe4-c6ed-4827-818d-d7e4ee4ca73b', 'f1e06ddf-24a5-4324-98f3-ce0e34447c1f', 0, 'Risk avoidance, since purchasing insurance eliminates the underlying risk entirely.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('71c23a36-1512-4fc1-8d7f-1b587b059c2f', 'f1e06ddf-24a5-4324-98f3-ce0e34447c1f', 1, 'Risk transference — shifting the FINANCIAL impact of a risk to a third party (the insurer) in exchange for a premium, without eliminating the underlying technical risk or vulnerability itself, which still exists and could still result in an actual breach event.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81af5f14-028b-44bb-bc6f-839687eacc0a', 'f1e06ddf-24a5-4324-98f3-ce0e34447c1f', 2, 'Risk mitigation, since buying insurance directly reduces the technical likelihood of a breach occurring.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5f0dbcc-1b12-4ab1-8b80-2e0c240cc41a', 'f1e06ddf-24a5-4324-98f3-ce0e34447c1f', 3, 'Risk acceptance, since purchasing insurance means formally taking no action of any kind regarding the risk.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee46cdc5-5543-4bc7-aea4-5c7e099c47c2', 'babb81b6-219d-4fa7-b256-f707fd4627c4', 0, 'An internal self-assessment, since only the company''s own internal staff can perform any form of compliance verification, and no external auditor is ever involved.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('40ce7039-8d5b-4e8d-80a2-34d126ebce98', 'babb81b6-219d-4fa7-b256-f707fd4627c4', 1, 'A compliance audit/attestation (e.g., against a framework like SOC 2 or ISO 27001) — performed by an independent third party specifically because customers generally trust an independent, objective assessment far more than a vendor''s own self-reported claims about their security posture, especially when entrusting that vendor with sensitive data.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62961621-e604-4047-9426-f800d8765a61', 'babb81b6-219d-4fa7-b256-f707fd4627c4', 2, 'A penetration test, since penetration tests are the only recognized form of compliance certification.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('544ce9bb-4433-451b-8639-4948b9a0fc11', 'babb81b6-219d-4fa7-b256-f707fd4627c4', 3, 'This type of verification does not exist; customers never require any form of security evidence before signing contracts.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d1d00ad-5ea2-4ccf-a31d-50313a0ca669', 'f8470633-1485-4c90-be97-57c7d7fc3bb4', 0, 'Risk assessment (or a broader risk management/governance program) — a recurring, formal process to identify current risks, evaluate whether existing controls adequately address them, document any identified gaps, and track remediation over time; a ONE-TIME assessment is insufficient since threats and the environment both change continuously.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dbaf13e3-e704-4ad5-8411-7e27ef8a82a4', 'f8470633-1485-4c90-be97-57c7d7fc3bb4', 1, 'This is called incident response, since incident response is performed proactively once per year regardless of whether an incident has occurred.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('521681a8-a628-4e22-965c-58af915a4844', 'f8470633-1485-4c90-be97-57c7d7fc3bb4', 2, 'This is called digital forensics, since forensics is conducted annually as a preventive measure rather than after an incident.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dba702d5-7184-43f3-a6d0-6f65c129c760', 'f8470633-1485-4c90-be97-57c7d7fc3bb4', 3, 'Formal, recurring risk assessment provides no real value once a company has been assessed a single time.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('efcad267-141a-46b6-b88f-a332f2732de0', 'eb273cca-098a-44c6-a51f-bca1a41eebdf', 0, 'An Acceptable Use Policy (AUP) — a formal document defining what employees are and are not permitted to do with company IT resources, typically requiring signed acknowledgment before granting system access, serving both as a behavioral guideline and as a legal/HR reference if violations occur.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c80b725-e935-481e-82f9-cf20262af0ed', 'eb273cca-098a-44c6-a51f-bca1a41eebdf', 1, 'A Business Impact Analysis, since BIAs are the standard document employees sign to acknowledge acceptable IT use.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7dcc27ce-f3b4-498a-b567-07b2a3733089', 'eb273cca-098a-44c6-a51f-bca1a41eebdf', 2, 'A Service Level Agreement, since SLAs define acceptable employee behavior regarding company IT systems.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b7948d9b-bdc4-48fa-879c-a30d523f67b3', 'eb273cca-098a-44c6-a51f-bca1a41eebdf', 3, 'Companies are legally prohibited from requiring employees to sign any IT usage agreement.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('de4ca0c4-e24c-4197-81de-f3dbf3aee3c2', '6a28f158-392a-4ca3-8be8-3076317fc824', 0, 'Security metrics/KPIs (Key Performance Indicators) as part of ongoing security governance — quantifiable, consistently-tracked measurements reported to leadership, enabling objective trend analysis over time and informed resource-allocation decisions, rather than relying on subjective impressions of security posture.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d95cb705-3a22-423f-b4d3-246a98c6fdeb', '6a28f158-392a-4ca3-8be8-3076317fc824', 1, 'This is called penetration testing, since pen testing is performed continuously to generate ongoing quantifiable trend metrics.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('846b8d65-2d82-413b-932b-8d8fbfdea158', '6a28f158-392a-4ca3-8be8-3076317fc824', 2, 'This is called digital forensics, since forensics produces the organization''s ongoing security trend metrics.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c88f20b1-0c8f-4f62-b286-c4d728b45cf0', '6a28f158-392a-4ca3-8be8-3076317fc824', 3, 'Tracking security metrics over time provides no actionable governance value.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
